-- 0001 foundation: system settings and the audit log.
-- Timestamps are ISO-8601 UTC strings. IDs are opaque text (UUIDv4/ULID generated by the app).

CREATE TABLE system_settings (
    key        TEXT PRIMARY KEY,
    value      TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE audit_events (
    id            TEXT PRIMARY KEY,
    occurred_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    actor_user_id TEXT,
    action        TEXT NOT NULL,
    target_type   TEXT,
    target_id     TEXT,
    outcome       TEXT NOT NULL CHECK (outcome IN ('success', 'failure', 'denied')),
    request_id    TEXT,
    ip            TEXT,
    details       TEXT NOT NULL DEFAULT '{}'
) STRICT;

CREATE INDEX idx_audit_events_occurred_at ON audit_events (occurred_at);
CREATE INDEX idx_audit_events_actor ON audit_events (actor_user_id, occurred_at);
CREATE INDEX idx_audit_events_action ON audit_events (action, occurred_at);
